import numpy as np

from slidesong import learn, suggest


def _synthetic(true_w, n_events=40, per_event=4, seed=0):
    """Preferences generated by a user whose weights are true_w."""
    rng = np.random.default_rng(seed)
    d = len(suggest.FEATURES)
    X, wt, groups = [], [], []
    for e in range(n_events):
        for _ in range(per_event):
            a, b = rng.normal(size=d), rng.normal(size=d)
            win, lose = (a, b) if a @ true_w > b @ true_w else (b, a)
            X.append(win - lose); wt.append(1.0); groups.append(e)
    return np.array(X), np.array(wt), np.array(groups)


def test_fit_learns_what_the_user_values():
    w0 = learn._w0()
    true_w = w0.copy()
    i = suggest.FEATURES.index("smile")
    true_w[i] *= 3  # this user cares a lot more about smiles
    X, wt, groups = _synthetic(true_w)
    w = learn.fit(X, wt)
    assert w[i] > w0[i]
    acc0, acc1 = learn.cross_val(X, wt, groups)
    assert acc1 >= acc0


def test_fit_keeps_signs_and_bounds():
    w0 = learn._w0()
    X, wt, groups = _synthetic(-w0, n_events=30)  # a user who wants the opposite of everything
    w = learn.fit(X, wt)
    nz = w0 != 0
    assert np.all(np.sign(w[nz]) == np.sign(w0[nz]))
    assert np.all(np.abs(w[nz]) >= learn.FLOOR * np.abs(w0[nz]) - 1e-9)
    assert np.all(np.abs(w[nz]) <= learn.CAP * np.abs(w0[nz]) + 1e-9)


def test_pairs_from_events():
    evs = [{"action": "set", "new": "n", "old": "o", "shown": ["x", "y"]},
           {"action": "reject", "old": "r", "shown": ["p", "q", "s", "t"]},
           {"action": "accept", "new": "k", "shown": ["u"]},
           {"action": "accept", "new": "m", "shown": ["z"], "source": "pin"}]
    prs = learn.pairs_from(evs)
    got = {(a, b): w for _, a, b, w in prs}
    assert got[("n", "o")] == 1.0 and got[("n", "x")] == 0.2
    assert ("p", "r") in got and ("t", "r") not in got
    assert got[("k", "u")] == 0.1 and got[("m", "z")] == 0.5


def test_stored_cue_comes_back_hashable():
    import json
    from slidesong import learn
    stored = json.loads(json.dumps({"lyric": "x", "words": ["a"], "concepts": [["a puddle", "charco"]]}))
    c = learn._cue_back(stored)
    assert c["words"] == {"a"} and hash(tuple(c["concepts"]))
